#!/usr/bin/env bash
# recipes/crate-foreign-types-shared--0-3-1/build.sh -- stage the foreign-types-shared 0.3.1 crate as
# an entry of the cargo directory source share/cargo/crates/ (docs/rust-crates.md).
# Generated by tools/make_crate_packages.py.
set -euo pipefail
dest="${CVC_INSTALL_DIR}/share/cargo/crates/foreign-types-shared-0.3.1"
mkdir -p "${dest}"
cp -R "${CVC_SOURCE_DIR}/." "${dest}/"
# cargo reads a directory-source entry's checksums from here. "package" is the
# Cargo.lock checksum, which cargo compares; no per-file hashes (the bundle's
# own sha256 covers the files).
printf '{"files":{},"package":"aa9a19cbb55df58761df49b23516a86d432839add4af60fc256da840f66ed35b"}\n' > "${dest}/.cargo-checksum.json"
